enum class StreamStatus { progress, eof, error };

struct StreamResult {
    StreamStatus status;
    std::size_t count;
    int error;
};

constexpr int io_chunk_size(std::size_t requested) noexcept {
    return requested > static_cast<std::size_t>((std::numeric_limits<int>::max)())
               ? (std::numeric_limits<int>::max)()
               : static_cast<int>(requested);
}

StreamResult send_some(Socket& socket, const std::uint8_t* data, std::size_t count) noexcept {
    if (!socket.valid()) {
        return StreamResult{StreamStatus::error, 0, kInvalidRequest};
    }
    if (count == 0 || data == nullptr) {
        return StreamResult{StreamStatus::error, 0, kInvalidRequest};
    }

    const int request = io_chunk_size(count);
    const OsHandle handle = handle_of(socket);

    for (;;) {
#if defined(_WIN32)
        const int sent = ::send(handle,
                                reinterpret_cast<const char*>(data),
                                request,
                                0);
        if (sent == SOCKET_ERROR) {
            const int code = ::WSAGetLastError();
            // Winsock cancellation is reported to the caller.
            return StreamResult{StreamStatus::error, 0, code};
        }
#else
        const ssize_t sent = ::send(handle,
                                    data,
                                    static_cast<std::size_t>(request),
                                    kSendFlags);
        if (sent < 0) {
            const int code = errno;
            if (code == kInterrupted) {
                continue;  // interrupted before any byte was accepted
            }
            return StreamResult{StreamStatus::error, 0, code};
        }
#endif
        if (sent == 0) {
            // send() reporting 0 never means progress and its errno is not fresh.
            return StreamResult{StreamStatus::error, 0, kZeroSendFailure};
        }
        return StreamResult{StreamStatus::progress, static_cast<std::size_t>(sent), 0};
    }
}

SendOutcome send_block(study_net::Socket& socket,
                       const std::uint8_t* data,
                       std::size_t count, std::size_t base = 0) {
    std::size_t accepted = 0;
    while (accepted < count) {
        const std::size_t requested = count - accepted;
        const study_net::StreamResult result =
            study_net::send_some(socket, data + accepted, requested);
        if (result.status == study_net::StreamStatus::progress) {
            accepted += result.count;
            std::cout << "SEND requested=" << requested
                      << " accepted=" << result.count
                      << " total=" << base + accepted << "\n";
        } else {
            const int code =
                result.status == study_net::StreamStatus::error ? result.error : 0;
            std::cout << "SEND requested=" << requested
                      << " accepted=0 status="
                      << (result.status == study_net::StreamStatus::eof ? "eof" : "error")
                      << " error=" << code << "\n";
            return SendOutcome{false, code, accepted};
        }
    }
    return SendOutcome{true, 0, accepted};
}

StreamResult receive_some(Socket& socket, std::uint8_t* data, std::size_t count) noexcept {
    if (!socket.valid()) {
        return StreamResult{StreamStatus::error, 0, kInvalidRequest};
    }
    if (count == 0 || data == nullptr) {
        return StreamResult{StreamStatus::error, 0, kInvalidRequest};
    }

    const int request = io_chunk_size(count);
    const OsHandle handle = handle_of(socket);

    for (;;) {
#if defined(_WIN32)
        const int received = ::recv(handle,
                                    reinterpret_cast<char*>(data),
                                    request,
                                    0);
        if (received == SOCKET_ERROR) {
            const int code = ::WSAGetLastError();
            // Winsock cancellation is reported to the caller.
            return StreamResult{StreamStatus::error, 0, code};
        }
#else
        const ssize_t received = ::recv(handle,
                                        data,
                                        static_cast<std::size_t>(request),
                                        0);  // blocking; no MSG_WAITALL, no nonblocking
        if (received < 0) {
            const int code = errno;
            if (code == kInterrupted) {
                continue;  // interrupted before any byte was delivered
            }
            return StreamResult{StreamStatus::error, 0, code};
        }
#endif
        if (received == 0) {
            return StreamResult{StreamStatus::eof, 0, 0};
        }
        return StreamResult{StreamStatus::progress, static_cast<std::size_t>(received), 0};
    }
}

template <std::size_t Capacity>
class ByteBuffer {
public:
    ByteBuffer() noexcept : bytes_{}, used_(0) {}

    // Append `count` readable bytes from the borrowed buffer `data`.
    // On failure, contents and size remain unchanged; no thread atomicity.
    // Copy only when the whole request fits. Empty append accepts null.
    bool append(const std::uint8_t* data, std::size_t count) noexcept {
        if (count == 0) {
            return true;  // explicit empty append, null is fine
        }
        if (data == nullptr) {
            return false;  // non-empty append needs a readable buffer
        }
        if (count > Capacity - used_) {
            return false;  // would overflow; reject before copying anything
        }
        for (std::size_t index = 0; index < count; ++index) {
            bytes_[used_ + index] = data[index];
        }
        used_ += count;
        return true;
    }

    const std::uint8_t* data() const noexcept { return bytes_.data(); }
    std::size_t size() const noexcept { return used_; }
    std::size_t remaining() const noexcept { return Capacity - used_; }

private:
    std::array<std::uint8_t, Capacity> bytes_;
    std::size_t used_;
}
;

bool shutdown_send(Socket& socket, int& error) noexcept {
    error = 0;
    if (!socket.valid()) {
        error = kInvalidRequest;
        return false;
    }

    const OsHandle handle = handle_of(socket);
#if defined(_WIN32)
    if (::shutdown(handle, SD_SEND) == SOCKET_ERROR) {
        error = ::WSAGetLastError();  // captured immediately; no retry policy
        return false;
    }
#else
    if (::shutdown(handle, SHUT_WR) != 0) {
        error = errno;  // captured immediately; no retry policy
        return false;
    }
#endif
    return true;
}
